/**
 * @mohammed_kashif/requestid
 *
 * Lightweight, configurable Express.js middleware that automatically
 * generates, validates, manages, and propagates unique HTTP request
 * identifiers.
 *
 * Every request deserves an identity.
 *
 * @module @mohammed_kashif/requestid
 */

import { generateUUID } from "./generators/uuid.js";
import { generateNanoId } from "./generators/nanoid.js";
import { invokeCustomGenerator, assertValidGenerator } from "./generators/custom.js";
import { applyPrefix, assertValidPrefix } from "./utils/formatter.js";

export { requestId } from "./middleware/requestId.js";
export { validateRequestId } from "./utils/validator.js";
export { generateUUID } from "./generators/uuid.js";
export { generateNanoId } from "./generators/nanoid.js";

/**
 * @typedef {object} GeneratorOptions
 * @property {"uuid"|"nanoid"} [strategy="uuid"] - Built-in strategy.
 * @property {string}          [prefix=""]       - ID prefix.
 * @property {Function}        [generator]       - Custom generator function.
 */

/**
 * Create a standalone ID generator function that honours the same
 * options object used by the middleware.  Useful for generating request
 * IDs outside of Express (e.g. plain http.Server, WebSocket upgrades,
 * CLI tools, or test helpers).
 *
 * @param {GeneratorOptions} [options={}]
 * @returns {() => string}
 *
 * @example
 * const generate = createRequestIdGenerator({ strategy: "nanoid", prefix: "job" });
 * const id = generate(); // "job_V1StGXR8_Z5jdHi6B"
 */
export function createRequestIdGenerator(options = {}) {
  const prefix    = options.prefix    ?? "";
  const strategy  = options.strategy  ?? "uuid";
  const generator = options.generator ?? undefined;

  assertValidPrefix(prefix);

  if (generator !== undefined) {
    assertValidGenerator(generator);
  } else if (!["uuid", "nanoid"].includes(strategy)) {
    throw new TypeError(
      `[@mohammed_kashif/requestid] Unknown strategy "${strategy}". Valid values: "uuid", "nanoid".`
    );
  }

  return function generate() {
    let raw;

    if (generator) {
      raw = invokeCustomGenerator(generator);
    } else if (strategy === "nanoid") {
      raw = generateNanoId();
    } else {
      raw = generateUUID();
    }

    return applyPrefix(raw, prefix);
  };
}
